import React from 'react';

const recordings = [
  { type: 'Fire Detected',     loc: 'Camera 02 - Parking',   date: 'May 24, 10:20 AM', bg: 'linear-gradient(135deg,#1a0500,#3d0f00)' },
  { type: 'Violence Detected', loc: 'Camera 03 - Corridor',  date: 'May 24, 10:10 AM', bg: 'linear-gradient(135deg,#0a0010,#200530)' },
  { type: 'Gun Detected',      loc: 'Camera 01 - Main Gate', date: 'May 24, 09:45 AM', bg: 'linear-gradient(135deg,#0a0a00,#1a1000)' },
];

export default function RecordingsPanel() {
  return (
    <div style={{ flex: 1, overflowY: 'auto', padding: '10px 12px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>Recent Recordings</span>
        <span style={{ fontSize: 10, color: '#3b82f6', cursor: 'pointer' }}>View All</span>
      </div>

      {recordings.map((r, i) => (
        <div key={i} style={{
          display: 'flex', alignItems: 'center', gap: 8,
          padding: '6px 0',
          borderBottom: i < recordings.length - 1 ? '1px solid #1e2d47' : 'none'
        }}>
          <div style={{ width: 50, height: 32, borderRadius: 4, background: r.bg, flexShrink: 0 }} />
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 11, fontWeight: 600, color: '#fff' }}>{r.type}</div>
            <div style={{ fontSize: 10, color: '#64748b' }}>{r.loc}</div>
            <div style={{ fontSize: 10, color: '#64748b' }}>{r.date}</div>
          </div>
          <span style={{ fontSize: 10, color: '#64748b', marginRight: 2 }}>20:00</span>
          <span style={{ fontSize: 20, color: '#3b82f6', cursor: 'pointer' }}>⬇</span>
        </div>
      ))}
    </div>
  );
}
